INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('b2e6be12-741e-4533-9344-dbba75c2c0a9', '788870d9-4155-42bd-940b-d92a5e945fd7', 'De acordo com a Constituição Federal de 1988, o empregado que desempenha funções consideradas penosas, insalubres ou perigosas faz jus a:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Bom Jesus - RS / Técnico Agrícola / Questão: 18', 'A alternativa correta reflete o disposto no art. 7º, XXIII, da CF: "adicional de remuneração para as atividades penosas, insalubres ou perigosas, na forma da lei." As demais alternativas não têm qualquer correspondência com o texto constitucional: não existe previsão de "declaração de mérito" (a), o exercício de atividade de risco não implica redução de vencimentos (b), tampouco há previsão de descanso em dobro nos feriados por conta da exposição a risco (c).', 1, true),
('1ba109e4-5a62-4f77-a79f-65193943f274', '788870d9-4155-42bd-940b-d92a5e945fd7', 'A Constituição Federal de 1988, em seu artigo 8º, prevê que é livre a associação profissional ou sindical. Sobre o tema, analise as assertivas abaixo: I. A lei não poderá exigir autorização do Estado para a fundação de sindicato, ressalvado o registro no órgão competente, vedadas ao Poder Público a interferência e a intervenção na organização sindical.II. É facultativa a participação dos sindicatos nas negociações coletivas de trabalho.III. O aposentado filiado tem direito a votar, porém não pode ser votado nas organizações sindicais.IV. Ninguém será obrigado a filiar-se ou a manter-se filiado a sindicato. Quais estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Conselho Regional dos Técnicos Industriais do Rio Grande do Sul CRT - RS / Técnico em Eletromecânica / Questão: 28', 'Os itens I e IV reproduzem fielmente o texto constitucional. O item I corresponde ao art. 8º, I: "a lei não poderá exigir autorização do Estado para a fundação de sindicato, ressalvado o registro no órgão competente, vedadas ao Poder Público a interferência e a intervenção na organização sindical." O item IV corresponde ao art. 8º, V: "ninguém será obrigado a filiar-se ou a manter-se filiado a sindicato." Já o item II está incorreto, pois o art. 8º, VI, prevê que a participação dos sindicatos nas negociações coletivas é OBRIGATÓRIA, e não facultativa. O item III também está incorreto, pois o art. 8º, VII, garante ao aposentado filiado o direito de votar E ser votado, e não apenas votar.', 2, true),
('508e4b86-1218-4132-b3ca-947918cbc1f1', '788870d9-4155-42bd-940b-d92a5e945fd7', 'Com base na Constituição Federal de 1988, assinale a alternativa correta sobre o salário mínimo.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Porto Mauá - RS / Operário Especializado / Questão: 39', 'A alternativa correta reproduz a essência do art. 7º, IV, da CF: "salário mínimo, fixado em lei, nacionalmente unificado, capaz de atender às suas necessidades vitais básicas e às de sua família com moradia, alimentação, educação, saúde, lazer, vestuário, higiene, transporte e previdência social, com reajustes periódicos que lhe preservem o poder aquisitivo, sendo vedada sua vinculação para qualquer fim." As demais alternativas estão erradas por atribuírem a fixação do salário mínimo a órgãos ou instrumentos que não têm essa competência constitucional: nem o TST, nem os Estados isoladamente, nem convenções coletivas, nem o Poder Judiciário têm poder para fixar o valor do salário mínimo, que é matéria de lei federal, de aplicação nacional.', 3, true),
('628ff282-cbb0-4c87-9cf9-7e6dc5c317db', '788870d9-4155-42bd-940b-d92a5e945fd7', 'Segundo as disposições do Art. 7º da Constituição Federal vigente, NÃO está entre os direitos garantidos aos trabalhadores urbanos e rurais o(a):', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Maçambará Prefeitura de Macambara - RS / Atendente de Unidade de Saúde / Questão: 13', 'A alternativa correta (isto é, a que NÃO corresponde a um direito literal) é a "d". O texto constitucional (art. 7º, XIX) apenas prevê a "licença-paternidade, nos termos fixados em lei", remetendo o prazo específico à legislação infraconstitucional (atualmente, o art. 10, §1º, do ADCT, fixa 5 dias, prorrogáveis por lei em caso de participação no programa Empresa Cidadã). A Constituição não fixa, ela própria, o prazo de "15 dias", o que torna essa alternativa incorreta como reprodução literal do texto constitucional. As demais alternativas correspondem fielmente aos incisos III, II, IX e XXI do art. 7º.', 4, true),
('e6c4fb0c-44cb-4cab-9b4b-9d2418d9d556', '788870d9-4155-42bd-940b-d92a5e945fd7', 'Com base na Constituição Federal, analise as assertivas abaixo sobre o direito de greve: I. A lei definirá os serviços ou atividades essenciais.II. Os abusos cometidos sujeitam os responsáveis às penas da lei.III. A lei disporá sobre o atendimento das necessidades inadiáveis da comunidade. Quais estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Instituto Federal de Educação, Ciência e Tecnologia Farroupilha IFFAR - BR / Técnico em Agropecuária / Questão: 11', 'As três assertivas estão corretas, correspondendo ao art. 9º, §1º, da CF: "a lei definirá os serviços ou atividades essenciais e disporá sobre o atendimento das necessidades inadiáveis da comunidade", e ao §2º, que trata das penas pelos abusos cometidos. Como todos os itens estão corretos, a resposta é I, II e III.', 5, true),
('a884b260-ba35-4a81-bd6f-152769cfc6b5', '788870d9-4155-42bd-940b-d92a5e945fd7', 'Previstos na Constituição Federal de 1988, o fundo de garantia por tempo de serviço (FGTS), o repouso semanal remunerado, as férias anuais remuneradas e a licença à gestante são alguns dos direitos dos trabalhadores:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2022 / Instituto de Assistência à Saúde dos Servidores Públicos do Rio Grande do Sul IPE SAUDE RS - RS / Técnico em Gestão de Saúde / Questão: 22', 'A resposta correta decorre do caput do art. 7º da CF: "são direitos dos trabalhadores urbanos e rurais, além de outros que visem à melhoria de sua condição social". Todos os direitos mencionados (FGTS, repouso semanal remunerado, férias e licença à gestante) estão previstos nesse mesmo artigo, aplicando-se tanto a trabalhadores urbanos quanto rurais, sem menção a trabalhadores informais, categoria não contemplada nesse rol constitucional específico.', 6, true),
('0e97b979-b34b-4eaa-9d33-18cf737df588', '788870d9-4155-42bd-940b-d92a5e945fd7', 'Nos termos do Art. 6º da Constituição Federal de 1988, são considerados direitos sociais, EXCETO:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2022 / Prefeitura de Monte Belo do Sul - RS / Operador de Máquinas / Questão: 37', 'A alternativa "e" é a exceção pedida, pois o "auxílio emergencial" não consta expressamente no rol do art. 6º, caput, da CF — trata-se de benefício criado por legislação específica em contextos emergenciais (como a pandemia de Covid-19), e não de um direito social permanentemente positivado no texto constitucional. As demais alternativas correspondem exatamente aos itens listados no art. 6º: educação, saúde, lazer e proteção à maternidade e à infância.', 7, true);
